<script lang="ts">
 // motion-site · profile: editorial · archetype: travel-essay · patterns: photo-led-hero·cost-selector·press-feedback · critique: P5 T4 C5 R5 A5 V5
 import { onMount } from 'svelte';
 import { tripCosts, daysToSave, dailySaving, foodRows, pounds, range, accorLink, ibisLink, IBIS_RATES, HOTEL_RATES, CHECKED, type Stay, type HotelStyle } from '$lib/switzerland';
 const scenery = [
  { file: 'grindelwald-winter.jpg', label: 'Grindelwald / beneath the Wetterhorn', alt: 'A wide snowy Grindelwald valley beneath sunlit alpine peaks', position: '65% center' },
  { file: 'interlaken-winter.jpg', label: 'Lake Brienz / the Interlaken region', alt: 'Blue Lake Brienz between snow-dusted mountains and wooded slopes', position: '60% center' },
  { file: 'lauterbrunnen-winter.jpg', label: 'Lauterbrunnen / the waterfall valley', alt: 'Winter sunlight over Lauterbrunnen village and its towering cliffs', position: '60% center' },
  { file: 'geneva.jpg', label: 'Geneva / our lakeside base', alt: 'The Jet d’Eau fountain above Lake Geneva', position: 'center' }
 ];
 let scene = $state(0);
 let rotating = $state(true);
 let touchStart = 0;
 function selectScene(index: number) { scene = (index + scenery.length) % scenery.length; rotating = false; }
 let nights = $state<Stay>(3);
 let style = $state<HotelStyle>('budget');
 let mountain = $state(false);
 let ready = $state(false);
 let copied = $state(false);
 let soundtrack: HTMLAudioElement;
 let soundtrackBlocked = $state(false);
 async function playSoundtrack() {
  try { await soundtrack.play(); soundtrackBlocked = false; }
  catch { soundtrackBlocked = true; }
 }
 let savingDays = $state<number | null>(null);
 const savingPlans = $derived(savingDays !== null && savingDays > 0 ? ([2, 3] as const).map(stay => {
  const plan = tripCosts('budget', stay);
  return { nights: stay, room: pounds(dailySaving(plan.room, savingDays!)!),
   roomEach: pounds(dailySaving(plan.room, savingDays!, 2)!),
   total: plan.total.map(amount => pounds(dailySaving(amount, savingDays!)!)).join('–'),
   totalEach: plan.total.map(amount => pounds(dailySaving(amount, savingDays!, 2)!)).join('–') };
 }) : []);
 const costs = $derived(tripCosts(style, nights, mountain));
 const budget = $derived(tripCosts('budget', nights));
 const bougy = $derived(tripCosts('bougy', nights));
 onMount(() => {
  void playSoundtrack();
  const motion = window.matchMedia('(prefers-reduced-motion: reduce)');
  rotating = !motion.matches;
  const respectMotion = () => { if (motion.matches) rotating = false; };
  motion.addEventListener('change', respectMotion);
  const sceneTimer = window.setInterval(() => { if (rotating && !document.hidden) scene = (scene + 1) % scenery.length; }, 6500);
  try { const p = JSON.parse(localStorage.getItem('stendo.switzerland.plan') || 'null'); if(p) { if(p.nights === 2 || p.nights === 3) nights = p.nights; if(p.style === 'budget' || p.style === 'bougy') style = p.style; mountain = p.mountain === true; } } catch { /* Storage is optional. */ }
  ready = true;
  const updateCountdown = () => { savingDays = daysToSave(); };
  updateCountdown();
  const countdownTimer = window.setInterval(updateCountdown, 1000);
  document.addEventListener('visibilitychange', updateCountdown);
  return () => { window.clearInterval(sceneTimer); motion.removeEventListener('change', respectMotion); window.clearInterval(countdownTimer); document.removeEventListener('visibilitychange', updateCountdown); };
 });
 $effect(() => { if(ready) { try { localStorage.setItem('stendo.switzerland.plan', JSON.stringify({ nights, style, mountain })); } catch { /* Private browsing. */ } } });
 async function copyPlan() {
  const text = `Switzerland wildcard: ${style === 'budget' ? 'Budget / ibis' : 'Bougy / MGallery'}, 19–${nights === 3 ? '22' : '21'} March 2027 (${nights} nights). Estimated total ${range(costs.total)} per couple, excluding the day trip. Day trip: £90 per person (£180 per couple), to consider separately and repay later. Choose a no-prepayment hotel rate to book now and pay at the hotel. This is a weekend budget, not an upfront bill: pay the hotel during your stay (confirm exact payment timing), and food and extras as you go. Food and extras are allowances; spending less reduces your actual total. Flights are Katie & Alex’s gift (£180 per couple); nothing to repay. Hotel rates and group availability need rechecking. Saturday excursion needs confirming. This is a preference, not a booking.`;
  try { await navigator.clipboard.writeText(text); copied = true; } catch { copied = false; }
 }
</script>

